 protected override void Dispose(bool disposing){if(disposing){timer.Dispose();frame.Dispose();audio.Dispose();foreach(Bitmap mark in fieldMarks.Values)mark.Dispose();}base.Dispose(disposing);}
 void ToggleFull(){full=!full;if(full){FormBorderStyle=FormBorderStyle.None;WindowState=FormWindowState.Maximized;}else{WindowState=FormWindowState.Normal;FormBorderStyle=FormBorderStyle.Sizable;ClientSize=new Size(1280,800);}}
 void StartGame(){StartMatch(false);}void StartPractice(){StartMatch(true);}
 void StartMatch(bool practice){if(!practice&&franchise.Fired){Open("league");return;}exhibition=false;Fixture fixture=franchise.UserGame;if(!practice&&fixture==null){franchise.Notice=franchise.Complete?"Season complete. Open Schedule to start next season.":"Bye or eliminated. Advance from Schedule or Playoffs.";Open("club");return;}game=new Simulation();game.Practice=practice;game.Difficulty=difficulty;int opponent=fixture==null?(franchise.UserTeam+1)%12:fixture.Opponent(franchise.UserTeam);franchise.Apply(game,opponent);game.NewGame();matchFixture=practice?-1:fixture.Id;screen="game";awarded=false;cameraZ=game.Spot-7;cameraX=0;selection=0;pendingThrow=0;stickReady=true;} void Open(string next){audio.Play("confirm");if(next!="game"){game.Charging=false;game.Charge=0;pendingThrow=0;}screen=next;selection=0;navTime=.18f;}
 int MenuCount(){if(IsBeta())return BetaCount();if(IsFront())return FrontRows().Count;return screen=="home"?6:screen=="pause"?8:screen=="club"?6:screen=="teams"?Roster.Teams.Length+1:screen=="agents"?10:screen=="calls"?game.PlayNames.Length+7:1;}
 bool QBMode(){return game.CanThrow;}
 void TickGame(){double now=watch.Elapsed.TotalSeconds;float dt=(float)Math.Max(0,Math.Min(.05,now-last));last=now;time+=dt;navTime-=dt;audio.SetContext(input.Focused,!game.Practice&&(screen=="game"||screen=="pause"||screen=="calls"||screen=="designer"||screen=="audio"));
  input.Context=screen!="game"?"menu":game.State==Phase.PreSnap?"presnap":QBMode()?"qb":game.State==Phase.Live||game.State==Phase.Loose?"runner":"menu";input.Poll();if(input.Pressed(Input.View))audio.Muted=!audio.Muted;if(hadPad&&!input.Connected&&screen=="game")Open("pause");hadPad=input.Connected;if(RaceNavigation()){Invalidate();return;}
  if(screen=="designer"){TickDesigner(dt);Invalidate();return;}if(screen=="game"){if(TickOnsideChoice())return;
   if(input.Pressed(Input.Start)||input.PausePressed||game.State==Phase.PreSnap&&input.Pressed(Input.B)){Open("pause");Invalidate();return;}
   game.Sprint=input.Sprint>.2f;game.LeadX=input.AimX*6;game.LeadZ=input.AimZ*7;game.PlacementX=input.MoveX*1.75f;game.PlacementZ=input.MoveZ*2;
   if(game.AmbulanceActive){if(input.Pressed(Input.A))game.SkipAmbulance();}else if(game.State==Phase.PreSnap){if(input.Pressed(Input.Left))game.CyclePlay(-1);if(input.Pressed(Input.Right))game.CyclePlay(1);if(input.Pressed(Input.X)){game.RunPlay=!game.RunPlay;game.Playbook=game.RunPlay?6:0;}
    if(input.Pressed(Input.RB)&&game.RequestOnsideTry()){Invalidate();return;}if(input.Pressed(Input.Y)){Open("calls");Invalidate();return;}if(input.Pressed(Input.A))game.Snap();
   }else if(game.State==Phase.Live){
    if(QBMode()){if(input.Pressed(Input.RClick)){game.ThrowAway();pendingThrow=0;}
     for(int i=0;i<passButtons.Length;i++)if(game.CanThrow&&input.Pressed(passButtons[i])&&!game.Charging){game.BeginPass(i);pendingThrow=passButtons[i];break;}
     if(pendingThrow!=0&&input.Released(pendingThrow)){game.ReleasePass();pendingThrow=0;}
     if(input.Pressed(Input.LB)){game.Handoff();pendingThrow=0;}
    }else{
     if(game.Charging){game.ReleasePass();pendingThrow=0;}
     if(Math.Abs(input.AimX)+Math.Abs(input.AimZ)<.25f)stickReady=true;if(stickReady&&(Math.Abs(input.AimX)>.65f||Math.Abs(input.AimZ)>.65f)){game.SkillMove(input.AimX,input.AimZ);stickReady=false;}if(input.Pressed(Input.X))game.Dive();if(input.Pressed(Input.B))game.SkillMove();if(input.Pressed(Input.Y))game.Jump();if(input.Pressed(Input.LB)){if(game.OptionLive&&game.Controlled.Z<=game.Spot)game.GiveOption();else game.Lateral();}
    }
   }else if(game.State==Phase.Loose){if(input.Pressed(Input.LB)){if(game.OptionLive&&game.Controlled.Z<=game.Spot)game.GiveOption();else game.Lateral();}}
   else if(game.State==Phase.Halftime){if(input.Pressed(Input.A))game.BeginSecondHalf();}else if(game.State==Phase.Dead||game.State==Phase.Opponent){if(input.Pressed(Input.A))game.Next();}
   else if(game.State==Phase.Kick){if(input.Pressed(Input.A))game.StopKick();}
   else if(game.State==Phase.Conversion){if(input.Pressed(Input.A))game.ChooseConversion(false);if(input.Pressed(Input.X))game.ChooseConversion(true);}
   else if(game.State==Phase.GameOver){AwardMatch();if(input.Pressed(Input.A))Open(exhibition?"exhibition":"franchisehub");}
   game.Update(dt,input.MoveX,input.MoveZ);while(game.Sounds.Count>0)audio.Play(game.Sounds.Dequeue());if(game.State==Phase.GameOver)AwardMatch();
   float follow=game.Controlled!=null?game.Controlled.Z:game.Spot;float fx=game.Controlled!=null?game.Controlled.X:0;if(game.State==Phase.Flight){follow=game.BallZ;fx=game.BallX;}if(game.AmbulanceActive){follow=game.InjuryPatient.Z;fx=game.InjuryPatient.X;}if(game.State==Phase.PreSnap){follow=game.Spot;fx=0;}
   if(game.State==Phase.Kick&&game.KickAnimating){follow=game.KickBallZ-4;fx=0;}float blend=1-(float)Math.Exp(-dt*10);cameraZ+=(Math.Max(-19,follow-(game.State==Phase.PreSnap?7:4))-cameraZ)*blend;cameraX+=(fx*.23f-cameraX)*blend;
  }else{
   int dir=0;if(input.Held(Input.Down)||input.MoveZ<-.55f)dir=1;if(input.Held(Input.Up)||input.MoveZ>.55f)dir=-1;if(screen=="calls"){if(input.Pressed(Input.Right))selection=(selection+1)%MenuCount();if(input.Pressed(Input.Left))selection=(selection+MenuCount()-1)%MenuCount();}if(screen=="calls")dir*=3;if(screen=="franchisehub"||screen=="exhibition"||screen=="settings"||screen=="coach")dir*=2;if(screen=="confirm"){if(input.Pressed(Input.Right))selection=1;if(input.Pressed(Input.Left))selection=0;}if(screen=="coachname")dir*=8;else if(screen=="quickteam")dir*=4;else if(screen=="home")dir*=2;if(IsBeta()&&screen!="audio"&&input.Pressed(Input.Right))selection=(selection+1)%MenuCount();if(IsBeta()&&screen!="audio"&&input.Pressed(Input.Left))selection=(selection+MenuCount()-1)%MenuCount();
   if(IsFront()&&screen!="club"&&screen!="confirm"){if(input.Pressed(Input.RB))selection=Math.Min(MenuCount()-1,selection+9);if(input.Pressed(Input.LB))selection=Math.Max(0,selection-9);}if(screen=="club"){dir*=3;if(input.Pressed(Input.Left))selection=(selection+MenuCount()-1)%MenuCount();if(input.Pressed(Input.Right))selection=(selection+1)%MenuCount();}if(navTime<=0&&dir!=0){selection=(selection+dir+MenuCount())%MenuCount();audio.Play("menu");navTime=.19f;}
   if(screen=="audio"){if(input.Pressed(Input.Left))AdjustAudio(selection,-.1f);if(input.Pressed(Input.Right))AdjustAudio(selection,.1f);}
   if(input.Pressed(Input.B)||input.Pressed(Input.Start)){if(IsBeta())Open(screen=="audio"?audioBack:screen=="home"?"home":screen=="coachname"?"coach":screen=="quickteam"?"exhibition":screen=="awards"?"trophies":screen=="historyteam"?"history":screen=="exhibition"||screen=="settings"?"home":"franchisehub");else if(IsFront())FrontBack();else if(screen=="pause"||screen=="calls")Open("game");else if(screen=="help"||screen=="stats")Open(returnScreen);else Open("home");}
   else if(input.Pressed(Input.A))ActivateSelection();
  }Invalidate();
 }
 void ActivateSelection(){if(IsBeta()){ActivateBeta();return;}if(IsFront()){ActivateFront();return;}
  if(screen=="home"){if(selection==0)StartGame();else if(selection==1)StartPractice();else if(selection==2)Open("club");else if(selection==3){returnScreen="home";Open("help");}else if(selection==4)ToggleFull();else Close();}
  else if(screen=="pause"){if(selection==0)Open("game");else if(selection==1){returnScreen="pause";Open("stats");}else if(selection==2){returnScreen="pause";Open("help");}else if(selection==3){difficulty=(difficulty+1)%3;game.Difficulty=difficulty;}else if(selection==4){Confirm("SIMULATE DRIVE","Available before snap. Uses ratings to finish this offensive possession.","pause",()=>{Open("game");game.SimDrive();});}else if(selection==5){Confirm("SIM REST OF GAME",exhibition?"Finish this quick game.":"Finish this game. Season result counts.","pause",()=>{Open("game");game.SimRest();AwardMatch();});}else if(selection==7)OpenAudioSettings();else Confirm("LEAVE MATCH",exhibition?"Leave this quick game?":"Leave with a 0-21 forfeit?","pause",()=>{if(matchFixture>=0){franchise.FinishGame(matchFixture,0,21);matchFixture=-1;awarded=true;}Open(exhibition?"exhibition":"franchisehub");});}  else if(screen=="club"){if(selection<3)club.Buy(selection);else if(selection==3)Open("agents");else if(selection==4)Open("teams");else Open("home");}else if(screen=="agents"){if(selection<9)roster.Sign(selection,club);else Open("club");}else if(screen=="teams"){if(selection<Roster.Teams.Length){roster.Team=selection;roster.Save();club.Notice="Team selected: "+Roster.Teams[roster.Team];}Open("club");}
  else if(screen=="help"||screen=="stats")Open(returnScreen);
  else if(screen=="calls"){int n=game.PlayNames.Length;if(selection<n){game.Playbook=selection;game.RunPlay=Simulation.IsRunCall(selection);game.UseCustom=false;}else if(selection==n)game.Punt();else if(selection==n+1)game.FieldGoal();else if(selection==n+2)game.Timeout();else if(selection==n+3)game.SimDrive();else if(selection==n+4){OpenDesigner();return;}else if(selection==n+5)game.RequestOnsideTry();Open("game");}
 }
